relief.code:
// Knockdown: plaster sprayed on in blobs about "size" mm across, then pressed flat with a trowel -- flat
// tops up to "amplitude" mm proud of the wall, with the wall showing between them. Gradient noise as the
// noise relief, through a smoothstep from "edge" to "edge" + "soft": every blob's top cut level. The
// slope bound is the noise relief's times the smoothstep's steepest, 1.5 / soft.
let peak = nzFbmLip(4u, 1.0, 0.5, 1.0);
let n = fbm3(q / size, 1u, 4u, 2.0, 0.5);
h = amplitude * smoothstep(edge, edge + soft, n.w / peak);
slope = amplitude / size * nzFbmLip(4u, 2.0, 0.5, NZ_GRAD_LIP_MEASURED) / peak * 1.5 / soft;

